-- CƠ SỞ DỮ LIỆU: QUẢN LÝ BÁN VÉ MÁY BAY
-- File 2/2: dữ liệu mẫu. Chạy SAU QLBanVeMayBay.sql, trên CSDL chưa có dữ liệu mẫu.
-- Gồm 10 sân bay, 5 máy bay (ghế do sp_MayBay_Them tự sinh), 2 nhân viên bán vé, 220 khách hàng,
-- 100 chuyến bay (90 đã bay từ 01/2026 đến 14/11/2026, 10 đang mở bán tới cuối tháng 12) và 660 vé (41 vé đã hủy).
-- Tổng cộng khoảng 997 dòng. Giá vé, ưu đãi khách mới / hạng thành viên và phí hủy tính đúng theo quy tắc của hệ thống.
-- Ngày giờ được tạo với mốc "hôm nay" là 16/11/2026.
USE QLBanVeMayBay
GO

IF EXISTS (SELECT * FROM SanBay) OR EXISTS (SELECT * FROM KhachHang)
BEGIN
    RAISERROR(N'CSDL đã có dữ liệu, script dữ liệu mẫu dừng lại.', 16, 1)
    SET NOEXEC ON
END
GO

SET XACT_ABORT ON
BEGIN TRAN

