) AS d(MaChuyenBay, CCCD, SoGhe, GiaGoc, TyLeGiam, GiaVe, PhuongThuc, NgayDat, TenDangNhap, TrangThai, NgayHuy, LyDoHuy, TyLePhiHuy, PhiHuy, TienHoan)
JOIN KhachHang k ON k.CCCD = d.CCCD
JOIN ChuyenBay c ON c.MaChuyenBay = d.MaChuyenBay
JOIN Ghe g ON g.MaMayBay = c.MaMayBay AND g.SoGhe = d.SoGhe
JOIN NhanVien n ON n.TenDangNhap = d.TenDangNhap

-- Kiểm tra đủ số dòng, thiếu thì hủy toàn bộ
IF (SELECT COUNT(*) FROM ChuyenBay) <> 100 OR (SELECT COUNT(*) FROM Ve) <> 660
BEGIN
    ROLLBACK
    RAISERROR(N'Số dòng thêm vào không khớp, đã hủy toàn bộ dữ liệu mẫu.', 16, 1)
END
ELSE
    COMMIT
